{
  "name": "tx_lock",
  "confidence": "medium",
  "docstring": "Acquires the TX lock and drains pending TX descriptors, invoking their completion callbacks and TX timestamp checks while IRQs are held off around each callback.",
  "subsystem": "mac",
  "var_renames": {
    "v0": "tx_list",
    "v1": "tx_desc",
    "v3": "irq_lock_count",
    "v4": "irq_disabled",
    "v5": "tx_done_cb",
    "v6": "next_lock_count",
    "v7": "irq_was_disabled",
    "result": "tx_status"
  },
  "struct_hints": [
    {
      "offset": 4,
      "meaning": "completion callback pointer for the TX descriptor"
    },
    {
      "offset": 8,
      "meaning": "argument passed to the TX descriptor callback"
    },
    {
      "offset": 12,
      "meaning": "TX timestamp check value or descriptor status"
    },
    {
      "offset": 16,
      "meaning": "descriptor flags; bit 0 tracks whether the descriptor needs queue accounting"
    }
  ]
}
